style.css:
@-moz-document domain("youtube.com") {
:root {
    /* Color Palette */
    --mwe-bg: #1c1a17;                  /*charchoal*/
    --mwe-bg-card: #25221e;             /*silver*/
    --mwe-bg-hover: #302c27;            /*goldish*/
    --mwe-text-main: #FFFFFF;           /*white*/
    --mwe-text-sub: #FEF3D8;           /*ivory*/
    --mwe-accent-rust: #b85b42;         /*brown/oragne*/
    --mwe-accent-amber: #d19a53;        /*amber*/
    --mwe-border: #3d3730;              /*dark*/
    --mwe-font: "Courier New", Courier, "Georgia", serif;
  }

  /* Core Structure & Backgrounds */
  ytd-app,
  #page-manager,
  #masthead-container,
  #guide-content,
  ytd-mini-guide-renderer,
  #contentContainer.tp-yt-app-drawer,
  ytd-watch-flexy,
  #columns,
  ytd-browse {
    background-color: var(--mwe-bg) !important;
  }

  /* Typography Overrides */
  body, 
  yt-formatted-string, 
  #video-title, 
  .title.ytd-video-primary-info-renderer,
  #channel-name,
  yt-icon,
  .ytd-channel-name {
    font-family: var(--mwe-font) !important;
    color: var(--mwe-text-main) !important;
  }

  #metadata-line span,
  #description-text,
  .style-scope ytd-video-meta-block,
  yt-formatted-string[has-link-only_] {
    color: var(--mwe-text-sub) !important;
  }

  /* Navigation Header & Search Bar */
  #masthead-container {
    border-bottom: 1px solid var(--mwe-border) !important;
  }

  #search-form #container {
    background-color: var(--mwe-bg-card) !important;
    border: 1px solid var(--mwe-border) !important;
    border-radius: 2px !important;
    box-shadow: none !important;
  }

  #search-icon-legacy {
    background-color: var(--mwe-bg-hover) !important;
    border: 1px solid var(--mwe-border) !important;
    border-left: none !important;
  }

  /* Video Cards & Thumbnails (Polaroid / Vinyl Sleeve Effect) */
  ytd-rich-item-renderer,
  ytd-grid-video-renderer,
  ytd-compact-video-renderer {
    background: var(--mwe-bg-card) !important;
    padding: 10px !important;
    border-radius: 3px !important;
    border: 1px solid var(--mwe-border) !important;
    transition: transform 0.2s ease, border-color 0.2s ease !important;
  }

  ytd-rich-item-renderer:hover,
  ytd-grid-video-renderer:hover,
  ytd-compact-video-renderer:hover {
    transform: translateY(-2px);
    border-color: var(--mwe-accent-rust) !important;
  }

  /* Analogue Film Warmth on Thumbnails */
  ytd-thumbnail img {
    border-radius: 2px !important;
    filter: sepia(0.20) contrast(0.92) saturate(0.85);
  }

  /* Buttons & Action Controls */
  yt-button-shape button,
  ytd-button-renderer paper-button {
    background-color: var(--mwe-bg-card) !important;
    color: var(--mwe-text-main) !important;
    border: 1px solid var(--mwe-border) !important;
    border-radius: 2px !important;
    font-family: var(--mwe-font) !important;
  }

  /* Subscribe & Primary Buttons */
  ytd-subscribe-button-renderer button,
  #subscribe-button paper-button,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled {
    background-color: var(--mwe-accent-rust) !important;
    color: #fcefe6 !important;
    border: none !important;
    border-radius: 2px !important;
    font-weight: bold !important;
    font-family: var(--mwe-font) !important;
  }

  /* Video Player Controls & Progress Bar */
  .ytp-play-progress.ytp-swatch-background-color,
  .ytp-swatch-background-color {
    background-color: var(--mwe-accent-rust) !important;
  }

  .ytp-scrubber-button {
    background-color: var(--mwe-accent-amber) !important;
  }

  /* Tag Cloud & Category Chips */
  yt-chip-cloud-chip-renderer[selected] {
    background-color: var(--mwe-accent-rust) !important;
    color: var(--mwe-text-main) !important;
  }

  yt-chip-cloud-chip-renderer {
    background-color: var(--mwe-bg-card) !important;
    border: 1px solid var(--mwe-border) !important;
    color: var(--mwe-text-sub) !important;
    border-radius: 2px !important;
  }

  /* Custom Slim Scrollbar */
  ::-webkit-scrollbar {
    width: 8px !important;
    background-color: var(--mwe-bg) !important;
  }

  ::-webkit-scrollbar-thumb {
    background-color: var(--mwe-border) !important;
    border-radius: 2px !important;
  }

  ::-webkit-scrollbar-thumb:hover {
    background-color: var(--mwe-accent-amber) !important;
  }
}
